// === Tab: mySketch.js ===
/* Created for #WCCChallenge "Waterfall"

This sketch is adapted from Waterfall by cys: https://www.shadertoy.com/view/ddtSR4, which manipulates the pixels in 
a texture to create a waterfall effect. When I tried running in openProcessing, the results were not identical. I suspect
this is due to a difference in the source image but there may also be due to differences between openProcessing and shadertoy.
I experimented with several different generative algorithms from the Lygia library and founnd that incorporting
worley noise worked pretty well.

All images are are low-res versions of my personal photos.



https://github.com/patriciogonzalezvivo/lygia/blob/main/generative/curl.glsl
*/

let myShader, img;
let imgs = ["sky3.jpg", "sky2.jpg", "blue_sky.jpg", "sky.jpg"]
//let imgs = ["sky2.jpg", "blue_sky.jpg", "sky.jpg", "ice.jpg", "jelly.jpg", "yellow_jelly.jpg", "flower.jpg"]
let images = []
let params = {
	i: 0,
}

async function setup() {
	let canvasSize = max(windowWidth, windowHeight);
	//createCanvas(canvasSize, canvasSize, WEBGL);
	createCanvas(windowWidth, windowHeight, WEBGL);
	pixelDensity(1);
	noStroke();

	const guiContainer = createDiv();
	guiContainer.id("gui");
	guiContainer.parent(document.body);

	gui = new lil.GUI({
		container: document.getElementById("gui"),
	});
	gui.add(params, "i", 0, 3, 1).name("Change image")
		.onChange(() => updateImage())

	//myShader = await createShader(vert, frag);
	myShader = await createShader(resolveLygia(vert), resolveLygia(frag));

	for (let img of imgs) {
		images.push(await loadImage(img))
	}

	updateImage()

}

function updateImage() {
	switch (params.i) {
		case 0:
			img = images[0];
			break;
		case 1:
			img = images[1];
			break;
		case 2:
			img = images[2];
			break;
		case 3:
			img = images[3];
			break;
		// case 4:
		// 	img = images[4];
		// 	break;
		// case 5:
		// 	img = images[5];
		// 	break;
		// case 6:
		// 	img = images[6];
		// 	break;
	}
}

function draw() {
	shader(myShader);

	myShader.setUniform("u_resolution", [width, height]);
	myShader.setUniform("u_time", millis() / 1000);
	myShader.setUniform("u_tex", img);

	rect(0, 0, width, height);
}

const frag = `#version 300 es
precision highp float;
out vec4 O;

uniform vec2 u_resolution;
uniform float u_time;
uniform sampler2D u_tex;

#include "lygia/generative/curl.glsl
#include "lygia/generative/worley.glsl


void main()
{
    vec2 pixel = gl_FragCoord.xy/u_resolution.xy;
    pixel.x = -0.75 - pixel.x; // 0.5
    pixel.y = 1.0 - pixel.y;
    pixel.y *= 80.0;
    pixel = 1.0/pixel;
    pixel.y += u_time*0.25;

    vec2 c = curl( pixel );
    vec2 w = worley2(pixel);
    vec3 col = texture(u_tex, w).rgb;
    O = vec4(col, 1.0);

	//O = texture(u_tex, 1.0/vec2(-0.75-uv.x, (1.0-uv.y)*80.0) + iTime*0.25);
}`;

const vert = `#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }`;

